M(quit_, r"""
public static void forget(java.util.UUID u, String name) {
  if (u == null) return;
  if (@PKG@.ZBuild.on(u)) @PKG@.ZBuild.set(u, name, false);
  @PKG@.ZWand.SEL.remove(u);
  @PKG@.ZMsg.LAST.remove(u);
  @PKG@.ZTick.forget(u);
}""")
